import React from 'react';

import { useNavigate } from 'react-router-dom';

import Page from '@components/Page';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { AuthContext } from '@contexts/AuthContext';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import PohDropdown from '@ui-kit/Dropdown';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import RoutePreviewHeader from './RoutePreviewHeader';
import RoutePreviewHiking from './RoutePreviewHiking';
import RoutePreviewMap from './RoutePreviewMap';
import { downloadGpx, IGetGPXStringTracks } from '../@helpers/gpx.helper';
import {
  getBaseRouteDataAsync,
  getRouteAccessData,
  getRouteObjectsAsync,
  IBaseRouteData,
  IRouteAccessData,
} from '../@services/routes.service';
import { IBaseRouteObjectLine, IRouteObject, RouteObjectType } from '../@types/routes.types';

interface IRoutePreviewProps {
  id_route: number;
}
const RoutePreview: React.FC<IRoutePreviewProps> = ({ id_route }) => {
  const [data, setData] = React.useState<IBaseRouteData>();
  const [accessData, setAccessData] = React.useState<IRouteAccessData[]>([]);
  const [routeObjects, setRouteObjects] = React.useState<IRouteObject[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  const authContext = React.useContext(AuthContext);
  const navigate = useNavigate();

  React.useEffect(() => {
    const fetchData = async () => {
      try {
        const d = await getBaseRouteDataAsync(id_route);
        setData(d);
        const d2 = await getRouteAccessData(id_route);
        setAccessData(d2);

        const d3 = await getRouteObjectsAsync(id_route);
        setRouteObjects(d3);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [id_route]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  if (!data)
    return (
      <PohAlert variant={AlertVariant.Warning}>Просмотр цели недоступен. Ошибка доступа</PohAlert>
    );

  const downloadFullGpx = (asRoute = false, join = false, onlyInDistance = false) => {
    const ro = routeObjects.toSorted((a, b) => a.order - b.order);
    let lines: IGetGPXStringTracks[] = ro
      .filter((r) => r.type === RouteObjectType.Line && (!onlyInDistance || r.is_in_distance))
      .map((r) => ({
        name: r.name,
        description: r.description,
        coordinates: (r as IBaseRouteObjectLine).points,
      }));
    if (join) {
      lines = [
        lines.reduce<IGetGPXStringTracks>(
          (acc, val) => {
            acc.description += val.name + ';\n';
            acc.coordinates.push(...val.coordinates);
            return acc;
          },
          { name: 'joined', description: '', coordinates: [] },
        ),
      ];
    }

    downloadGpx(
      lines,
      ro
        .filter((r) => r.type === RouteObjectType.Point)
        .map((r) => ({ name: r.name, description: r.description, coordinate: r.coordinates })),
      {
        asRoute,
        name: data.routeData.name,
        description: data.routeData.description,
        author: data.routeData.author.name,
        date: new Date(data.routeData.dateCreate ?? new Date()),
      },
    );
  };

  const menuActions: Record<string, (e: MouseEvent) => void> = {
    'Экспорт в GPX': () => downloadFullGpx(true, false, false),
    'Экспорт в GPX одной ниткой': () => downloadFullGpx(true, true, false),
    'Экспорт в GPX только "в дистанции"': () => downloadFullGpx(true, false, true),
    'Экспорт в GPX (трек)': (e) => downloadFullGpx(false, e.ctrlKey || e.shiftKey, e.altKey),
  };

  return (
    <section>
      <Page title={data.routeData.name}>
        <PohBreadcrumbs
          data={[
            { href: `/routes`, text: 'Маршруты' },
            { href: `/routes/${id_route}`, text: data.routeData.name, active: true },
          ]}
        />
        <PohContainer>
          <PageHeader title={data.routeData.name} subtitle={data.routeData.description}>
            {(data.routeData.author.id === authContext.user?.id ||
              accessData.find((x) => x.idUser === authContext.user?.id)) && (
              <PohButton
                size={ButtonSize.Small}
                onClick={() => navigate(`/routes/${id_route}/edit`)}
              >
                Редактировать
              </PohButton>
            )}
            &nbsp;
            <PohDropdown
              onClick={(e) => e.stopPropagation()}
              menu={Object.entries(menuActions).map(([label, callback]) => {
                if (label.startsWith('---'))
                  return (
                    <li key={`bottom-level-menu-item-${label}`}>
                      <hr className="dropdown-divider" />
                    </li>
                  );

                return (
                  <div
                    key={`bottom-level-menu-item-${label}`}
                    className="dropdown-item"
                    onClick={(e) => callback(e as any)}
                  >
                    {label}
                  </div>
                );
              })}
            >
              <PohButton size={ButtonSize.Small}>Скачать GPX</PohButton>
            </PohDropdown>
          </PageHeader>
          <PohRow>
            <PohCol sm={12}>
              <RoutePreviewHeader
                className="mt-n2 mb-2"
                baseRouteData={data}
                routeObjects={routeObjects}
              />
              <RoutePreviewMap
                baseRouteData={data}
                routeObjects={routeObjects}
                style={{ height: 480 }}
              />
            </PohCol>
          </PohRow>
          <PohRow className="mt-4">
            <PohCol sm={9}>
              <h5>Походы по маршруту</h5>
              <RoutePreviewHiking id_route={id_route} />
            </PohCol>
            <PohCol sm={3}>
              <PohRow>
                <PohCol sm={5} className="text-end text-muted">
                  Создан
                </PohCol>
                <PohCol sm={5}>{new Date(data.routeData.dateCreate).toLocaleDateString()}</PohCol>
              </PohRow>
              <PohRow>
                <PohCol sm={5} className="text-end text-muted">
                  Редакторы
                </PohCol>
                <PohCol sm={5}>
                  {accessData.map((editor) => {
                    return (
                      <PohAva
                        key={editor.id}
                        src={editor.photo}
                        width="1.7em"
                        alt={[editor.name, editor.surname].join(' ')}
                        title={[editor.name, editor.surname].join(' ')}
                        colorize
                      />
                    );
                  })}
                </PohCol>
              </PohRow>
            </PohCol>
          </PohRow>
        </PohContainer>
      </Page>
    </section>
  );
};

export default RoutePreview;
