import React, { HTMLAttributes } from 'react';

import * as L from 'leaflet';

import 'leaflet-fullscreen/dist/Leaflet.fullscreen.min';
import 'leaflet-fullscreen/dist/leaflet.fullscreen.css';

import 'leaflet/dist/leaflet.css';

import { watermarkToMap } from '@apps/Routes/@helpers/addToMap.helper';
import { formatDistance } from '@helpers/formatHelper';
import { getDefaultTileLayer, getMap, setDefaultMapView } from '@helpers/leafletHelper';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import { TEMPORARY_LINE_DASH_ARRAY, TEMPORARY_POINT_OPACITY } from '../@const/routeObjects.const';
import { getDivIcon, setMarkerObstacle } from '../@helpers/leaflet.helper';
import { IBaseRouteData } from '../@services/routes.service';
import {
  IBaseRouteObjectLine,
  IBaseRouteObjectPoint,
  IRouteObject,
  RouteObjectType,
} from '../@types/routes.types';
import ElevationChart from '../RouteEditorNew/components/Elevation/ElevationChart';
import RoutesEditorListItem from '../RouteEditorNew/components/RoutesEditorSidebar/RoutesEditorListItem';

interface IRoutePreviewMapProps extends HTMLAttributes<HTMLDivElement> {
  baseRouteData: IBaseRouteData;
  routeObjects: IRouteObject[];
}

const RoutePreviewMap = ({ baseRouteData, routeObjects, ...rest }: IRoutePreviewMapProps) => {
  const mapContainerRef = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);
  const layersRef = React.useRef<L.FeatureGroup>(new L.FeatureGroup());
  const cursorRef = React.useRef<L.Marker>(new L.Marker([0, 0]));

  React.useEffect(() => {
    if (!mapContainerRef.current) return;
    mapRef.current = getMap(mapContainerRef.current, { fullscreenControl: true });

    getDefaultTileLayer().addTo(mapRef.current);
    setDefaultMapView(mapRef.current);
    watermarkToMap(mapRef.current);

    layersRef.current.addTo(mapRef.current);
    cursorRef.current.addTo(mapRef.current);
  }, []);

  React.useEffect(() => {
    layersRef.current.clearLayers();
    routeObjects.forEach((routeObject) => {
      if (routeObject.type === RouteObjectType.Line) {
        const pl = new L.Polyline(routeObject.points, {
          color: routeObject.color,
          weight: routeObject.width,
          opacity: routeObject.opacity / 100,
          dashArray: routeObject.is_in_distance ? undefined : TEMPORARY_LINE_DASH_ARRAY,
        });

        pl.bindTooltip(
          [routeObject.name, routeObject.description, formatDistance(routeObject.distance)].join(
            '\n',
          ),
        );
        pl.addTo(layersRef.current);
      } else {
        // setMarkerStyles(marker, {
        //   color: routeObject.color,
        //   opacity: routeObject.is_in_distance ? 1 : TEMPORARY_POINT_OPACITY,
        // });

        if (routeObject.obstacle) {
          const marker = L.marker(routeObject.coordinates, { icon: getDivIcon() });

          setMarkerObstacle(marker, routeObject.obstacle);
          marker.addTo(layersRef.current);
        } else {
          const marker = new L.CircleMarker(routeObject.coordinates, {
            color: routeObject.color,
            opacity: routeObject.is_in_distance ? 1 : TEMPORARY_POINT_OPACITY,

            radius: 3,
          });
          marker.bindTooltip([routeObject.name, routeObject.description].join('\n'));
          marker.addTo(layersRef.current);
        }
      }
    });

    const bounds = layersRef.current.getBounds();
    if (bounds.isValid()) {
      mapRef.current?.fitBounds(bounds);
    }
    //
  }, [routeObjects]);

  const points = React.useMemo(() => {
    const ppp: [number, number, number][] = [];
    (
      routeObjects.filter(
        (r) => r.type === RouteObjectType.Line && r.is_in_distance,
      ) as IBaseRouteObjectLine[]
    )
      .toSorted((a, b) => a.order - b.order)
      .forEach((ro) => {
        ppp.push(...(ro.points as [number, number, number][]));
      });

    return ppp;
  }, [routeObjects]);

  return (
    <div>
      <PohRow>
        <PohCol sm={9}>
          <div {...rest} ref={mapContainerRef} />
        </PohCol>
        <PohCol sm={3} style={{ overflowY: 'auto', height: 480 }}>
          <PohList
            data={routeObjects.map((x) => {
              return {
                key: x.id,
                className: 'p-0',
                action: true,
                onClick: () => {
                  if (x.type === RouteObjectType.Line) {
                    mapRef.current?.flyToBounds(x.points);
                  } else {
                    mapRef.current?.flyTo(x.coordinates, mapRef.current?.getMaxZoom());
                  }
                },
                content: <RoutesEditorListItem routeObject={x} key={x.id} />,
              };
            })}
          />
        </PohCol>
      </PohRow>
      <ElevationChart
        points={points}
        poi={
          routeObjects.filter((ro) => ro.type === RouteObjectType.Point) as IBaseRouteObjectPoint[]
        }
        onCursorMove={(point) => {
          cursorRef.current.setLatLng(point);
          mapRef.current?.panTo(point);
        }}
        onEndCursorMove={() => {
          cursorRef.current.setLatLng([0, 0]);
        }}
        onStartCursorMove={() => {}}
      />
    </div>
  );
};

export default RoutePreviewMap;
