import React, { HTMLAttributes } from 'react';

import { Link } from 'react-router-dom';

import { getHikingListWithPagination } from '@apps/Hiking/@services/hiking.service';
import { IHikingListItem } from '@apps/Hiking/@types/hikingList.types';
import OneHikingListItem from '@apps/Hiking/list/HikingListsPage/OneHikingListItem';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohList from '@ui-kit/List';

interface IRoutePreviewHikingProps extends HTMLAttributes<HTMLDivElement> {
  id_route: number;
}

const RoutePreviewHiking = ({ id_route, ...rest }: IRoutePreviewHikingProps) => {
  const [data, setData] = React.useState<IHikingListItem[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  React.useEffect(() => {
    const fetchData = async () => {
      try {
        const { data: d0 } = await getHikingListWithPagination({ id_route });
        setData(d0);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [id_route]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <div {...rest}>
      <PohList
        className="mt-2"
        data={data.map((x: any) => ({
          key: x.id,
          as: Link,
          to: `/hiking/${x.id}`,
          action: true,
          style: { textDecoration: 'none' },
          content: <OneHikingListItem item={x} />,
        }))}
      />
    </div>
  );
};

export default RoutePreviewHiking;
